import{_ as t,o,c as n,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"en/settings.md","filePath":"en/settings.md","lastUpdated":null}'),a={name:"en/settings.md"};function s(i,e,l,d,h,c){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>The <strong>Settings</strong> page groups options on the left: General, Appearance, Network, Kernel, About. Setting cards can be collapsed from their headers.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><ul><li><strong>Working directory</strong>: where dsh starts; empty uses <code>workspace</code> under the config directory.</li><li><strong>Port</strong>: Auto (recommended; picks a free port from 3080) or manual.</li><li><strong>Close behavior</strong>: hide to tray or quit; “ask each time” or “remember choice”.</li></ul><h3 id="new-tab-search" tabindex="-1">New tab &amp; search <a class="header-anchor" href="#new-tab-search" aria-label="Permalink to &quot;New tab &amp; search&quot;">​</a></h3><ul><li><p><strong>Default search engine</strong>: used when the address bar receives something that is not a URL, and by the built-in new tab page (Baidu / Sogou / 360 / Bing / Google / DuckDuckGo).</p></li><li><p><strong>New tab</strong>: what the <strong>+</strong> button in the tab bar opens — the <strong>built-in new tab page</strong> (a search box plus shortcuts) or a <strong>custom URL</strong>.</p></li><li><p><strong>Site shortcuts</strong>: a list of name + URL entries shown on the built-in new tab page for one-click access.</p></li><li><p><strong>Restore defaults</strong>: reset everything and restart dsh.</p></li></ul><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><ul><li><strong>Theme</strong>: System / Light / Dark — takes effect immediately.</li><li><strong>Language (two-level menu)</strong>: pick 中文 / English, plus an extended translation (zh: Simplified / Anime / Classical Chinese / Traditional Chinese; en: English / Pirate / Shakespearean). Extended translations are <strong>text overlays</strong>, apply only to the current language, and never modify dsh settings.</li><li><strong>Zoom</strong>: 50%–200% (applies to the shell window and the embedded webview).</li><li><strong>Ignore OS scaling</strong>: prompts for a restart to take effect.</li></ul><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><ul><li><strong>npm registry</strong>: official registry / npmmirror.</li><li><strong>Proxy</strong>: enable + protocol (HTTP / SOCKS5) + host + port + <strong>proxy scope</strong> (npm installs/downloads, Node download &amp; deploy, kernel update checks). Currently the npm scope actually routes through the proxy; Node download and update-check proxy support are follow-ups.</li></ul><h2 id="kernel" tabindex="-1">Kernel <a class="header-anchor" href="#kernel" aria-label="Permalink to &quot;Kernel&quot;">​</a></h2><ul><li><strong>Start / Stop / Restart</strong>: control the dsh server directly, with a live status tag.</li><li><strong>Apply now</strong>: persist runtime changes and restart dsh.</li><li><strong>Kernel source</strong>: Bundled (installed into the app dir, run with the built-in Node) or Global.</li><li><strong>Node runtime</strong>: Electron built-in / System (≥ 20) / Local deploy; <strong>npm source</strong>: System / Bundled (downloaded) / Local Node’s own.</li><li><strong>Launcher path</strong>: shown only in Global mode; pick the file with a file dialog.</li><li><strong>Kernel updates</strong>: check on startup, include pre-releases, and a manual check / update.</li><li><strong>Version / uninstall</strong>: browse and <strong>install / switch</strong> to any historical version; <strong>Uninstall</strong> stops dsh first, then shows the install wizard.</li></ul><div class="warning custom-block"><p class="custom-block-title">Upgrade / switch / uninstall</p><p>These operations <strong>force-stop all running dsh instances first</strong> (they ask for confirmation if one is running). After an upgrade or switch, dsh restarts automatically; on failure the app detects the occupation cause and reports it.</p></div><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><ul><li>Shows the app version and runtime architecture.</li><li><strong>Auto update</strong>: check for a new app version on startup and download it in the background; <strong>Include pre-releases</strong>; <strong>Developer mode</strong> (F12 toggles DevTools).</li></ul><blockquote><p>Theme and the base language still mirror dsh’s own <code>~/.dsh/settings.yaml</code>; the app’s own settings (General / Network / Kernel / About, etc.) live in the app <strong>config directory</strong> <code>settings.json</code> (default <code>~/.config/dsh_shell</code>, <code>dsh_shell_dev</code> in dev; selectable in the wizard/settings, with migration).</p></blockquote>',16)])])}const u=t(a,[["render",s]]);export{p as __pageData,u as default};
